import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const webDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const source = path.resolve(webDir, "../contracts/bindings/auction/src/index.ts");
const target = path.join(webDir, "lib/contract/auction.ts");

// Copied instead of installed: the bindings package pins @stellar/stellar-sdk 16 and the web uses 17.
const header =
  "// Copy of contracts/bindings/auction/src/index.ts (generated by G1 with scripts/bindings.sh).\n" +
  "// Do not edit by hand: run `npm run bindings:sync` after G1 regenerates the bindings.\n";

fs.mkdirSync(path.dirname(target), { recursive: true });
fs.writeFileSync(target, header + fs.readFileSync(source, "utf8").replace(/\r\n/g, "\n"));
console.log(`${path.relative(webDir, target)} <- ${path.relative(webDir, source)}`);
